import json,re
def last_boxed(s):
    # find last \boxed{...} with brace matching
    idx=s.rfind('\\boxed{')
    if idx<0: return None
    i=idx+len('\\boxed{'); depth=1; out=[]
    while i<len(s) and depth>0:
        c=s[i]
        if c=='{': depth+=1
        elif c=='}':
            depth-=1
            if depth==0: break
        out.append(c); i+=1
    return ''.join(out).strip() if depth==0 else None

def norm(x):
    if x is None: return None
    x=x.replace(',','').replace('$','').replace(' ','').strip().rstrip('.')
    return x

for step in [0,50,100]:
    rows=[json.loads(l) for l in open(f'/workspace/results/run100/val_generations/{step}.jsonl')]
    fp=[];fn=[];nobox=0;boxwrong_scored1=0
    for r in rows:
        sc=r['score']; gt=norm(r['gts']); b=norm(last_boxed(r['output']))
        if b is None: nobox+=1
        if sc==1 and (b is None or b!=gt):
            boxwrong_scored1+=1
            if len(fp)<4: fp.append((r['gts'],b,r['output'][-300:]))
        if sc==0 and b==gt:
            if len(fn)<4: fn.append((r['gts'],b,r['output'][-200:]))
    print(f'step {step}: n={len(rows)} no-box={nobox} score1-but-lastbox-not-gt={boxwrong_scored1} score0-but-box==gt~={len(fn)}')
    for x in fp: print('  FP gt=',x[0],'lastbox=',x[1],'tail=',repr(x[2][-200:]))
    for x in fn: print('  FN gt=',x[0],'lastbox=',x[1],'tail=',repr(x[2][-160:]))
EOF

